/* mover.h: the servant is a module, the serviced type stays opaque */
struct position { int x, y; };
struct movable {                       /* capability the servant requires */
    void (*get)(const void *self, struct position *out);
    void (*set)(void *self, struct position p);
};
void mover_move_to(void *self, const struct movable *ops, struct position to);

/* caller: */
mover_move_to(&circle, &circle_movable, (struct position){3, 4});
